import sys; sys.path.insert(0, "/workspace/probe")
from dnskit import *
SCEN = sys.argv[2]
def handler(q):
    r = Response(q)
    if SCEN == "rootname":
        r.add_answer("", "A", 300, A("1.2.3.4"))
        r.add_answer(".", "NS", 300, name("ns1.example.com"))
    elif SCEN == "ch_class":
        r.add_answer("example.com", "TXT", 300, TXT("chaos"), rrclass="CH")
        r.add_answer_raw("example.com", 1, 99, 300, A("1.2.3.4"))
    elif SCEN == "only_add":
        r.add_additional("ns1.example.com", "A", 60, A("5.6.7.8"))
    elif SCEN == "opt_flags":
        r.add_answer("example.com", "A", 300, A("1.2.3.4"))
        r.add_additional("", "OPT", 0x0100, OPT(1232, 0, 0, 0x8000, b"\x00\x03\x00\x00"), rrclass=1232)
    return r
serve(handler, port=int(sys.argv[1]), log=False)
